/**
 * ============================================================================
 * GREGG SHORTHAND SVG PATHS DATABASE
 * ============================================================================
 *
 * PURPOSE:
 * Pre-computed SVG path definitions for all Gregg shorthand strokes.
 * Contains context-aware variants (head, tail, after specific strokes).
 *
 * SIZE: 5,210 lines, ~216 KB
 *
 * STRUCTURE:
 * PATHS = {
 *   "STROKE_NAME": {
 *     "variant_name": {
 *       dp: {x: number, y: number},  // Delta position (pen movement after stroke)
 *       paths: [string, ...]          // SVG path data (Bézier curves)
 *     }
 *   }
 * }
 *
 * PATH VARIANTS:
 * 1. default         - Standard stroke (standalone)
 * 2. default_head    - At word beginning (incoming connection)
 * 3. default_tail    - At word end (outgoing connection)
 * 4. after_GreggX    - Context-specific (after stroke X)
 * 5. before_GreggY   - Context-specific (before stroke Y)
 *
 * SVG PATH FORMAT:
 * - "m x,y" - Move to absolute position
 * - "c x1,y1 x2,y2 x,y" - Relative cubic Bézier curve
 * - "C x1,y1 x2,y2 x,y" - Absolute cubic Bézier curve
 * - "l x,y" - Relative line
 * - "L x,y" - Absolute line
 *
 * DELTA POSITION (dp):
 * Indicates where pen should move after drawing this stroke.
 * Used for proper spacing and flow to next stroke.
 *
 * MATHEMATICAL FOUNDATION:
 * - Based on Šarman 2008 paper: "Geometry of Gregg Shorthand"
 * - G¹ continuous joins (shared tangent)
 * - G² continuous joins (shared curvature) where applicable
 * - Bézier curves approximate circular arcs with <0.1% error
 *
 * STROKE MODELS (referenced in gregg.js):
 * - ER (East Right): Rightward curve, short
 * - EL (East Left): Leftward curve, short
 * - SW (Southwest): Diagonal down-left
 * - SWL (Southwest Left): Diagonal down-left with left curve
 * - SWR (Southwest Right): Diagonal down-left with right curve
 * - SE (Southeast): Diagonal down-right
 * - NE (Northeast): Diagonal up-right
 * - C (Circle): Vowel circle (a, e, i, o, u)
 * - P (Point): Dot/aspiration
 * Numbers indicate length (7=short, 14=long, 21=extra long)
 *
 * CONTEXT-AWARE RENDERING:
 * Strokes adapt their shape based on neighbors:
 * - "K.default_head" used when K starts word
 * - "K.default_tail" used when K ends word
 * - "R.after_GreggF" used when R follows F
 * This creates smooth, human-like connections.
 *
 * SOURCE:
 * Generated from Grascii editor's path definitions
 * Original: https://github.com/grascii/grascii-editor
 * Based on official Gregg Pre-Anniversary Edition (1916)
 *
 * USAGE:
 * const kHeadPath = PATHS.K.default_head;
 * const dp = kHeadPath.dp;  // Get pen movement
 * const svgPath = kHeadPath.paths[0];  // Get SVG path data
 *
 * LICENSE:
 * Adapted from Grascii project (MIT License)
 * Gregg shorthand system is in public domain
 *
 * ============================================================================
 */

